    private void kelompokkanHalamanRanap() {
        halamanRanap.clear();
        for (SeksiRanap s : seksiRanap) {
            if (s.panel == null) {
                continue;
            }
            HalamanRanap h = new HalamanRanap(s.judul);
            h.anggota.add(s);
            halamanRanap.add(h);
        }
    }

